"""COM315ARENA strategy module.

This module provides the decide() function that controls your bot's behavior.
Import it in your client:

    from strategy import decide

    # Each tick:
    command = decide(game_state)
    if command:
        sock.sendall((command + "\n").encode())

The strategy logic is pre-compiled. All players use the same AI.
Your competitive edge comes from networking, not from modifying this file.

Supported Python versions: 3.10, 3.12, 3.14
"""

import marshal as _m, base64 as _b, types as _t, sys as _s

_BLOBS = {
    "3.10": (
        ""
    ),
    "3.12": (
        ""
    ),
    "3.14": (
        ""
    ),
}

_ver = f"{_s.version_info.major}.{_s.version_info.minor}"
if _ver not in _BLOBS:
    _available = ", ".join(sorted(_BLOBS.keys()))
    raise RuntimeError(
        f"strategy.py does not support Python {_ver}. "
        f"Supported versions: {_available}"
    )

_code = _m.loads(_b.b64decode(_BLOBS[_ver]))
_mod = _t.ModuleType("_strategy_impl")
exec(_code, _mod.__dict__)
decide = _mod.decide
